export const careSources=[{title:'VCA: повседневный уход за шерстью',url:'https://vcahospitals.com/know-your-pet/grooming-and-coat-care-for-your-dog'},{title:'AKC: спокойное знакомство щенка с грумингом',url:'https://www.akc.org/expert-advice/dog-breeding/setting-puppies-success-handling-grooming/'}];
const shortCoat=new Set(['DOG-AMERICAN-BULLY','DOG-AMSTAFF','DOG-PITBULL','DOG-BULL-TERRIER','DOG-DOBERMAN','DOG-MINIATURE-PINSCHER','DOG-GERMAN-PINSCHER','DOG-BEAGLE','DOG-PUG','DOG-BULLDOG']);
const curlyCoat=new Set(['DOG-MALTIPOO','DOG-POODLE','DOG-BICHON']);
export function careFor(service){
 const id=service?.id||'',cat=id.startsWith('CAT-');
 if(id==='CAT-SPHYNX')return {kind:'hairless',summary:'Сфинксу подбирают бережный уход за кожей; вычёсывание шерсти и стрижка ему не нужны.',home:['Бережно очищайте загрязнения без жёстких щёток и трения. Подходящую косметику и частоту ухода подбирайте по состоянию кожи.','Не используйте шампунь для людей и лечебные средства без назначения ветеринарного врача.','После мытья аккуратно просушивайте кожу и обеспечьте комфортную температуру без перегрева.'],avoid:['Не советовать вычёсывание, экспресс-линьку, стрижку и бритьё.'],sources:careSources};
 if(shortCoat.has(id))return {kind:'short',summary:'Задача ухода за короткой шерстью — убрать загрязнения и отмершие волоски, аккуратно высушить шерсть и привести в порядок когти. Стрижка или бритьё корпуса обычно не нужны.',home:['Между визитами мягко проходите шерстью подходящей щёткой или резиновой рукавицей, без сильного нажима.','После прогулки очищайте лапы; имеющиеся складки бережно очищайте и просушивайте.','Для купания используйте шампунь для собак, тщательно смывайте его и просушивайте питомца. Частоту подбирают по состоянию кожи и загрязнению, без универсального графика.'],avoid:['Не обещать модельную стрижку или бритьё корпуса.','Не включать бальзам, парфюм, маску и лечебные процедуры, если их нет в выбранном комплексе.'],sources:careSources};
 if(curlyCoat.has(id))return {kind:'curly',summary:'Для мягкой кудрявой шерсти важны аккуратное расчёсывание, профилактика колтунов и длина, которую получается поддерживать дома. Состав салонного ухода берётся из карточки выбранной породы.',home:['Между визитами бережно расчёсывайте шерсть подходящими инструментами, уделяя внимание зонам за ушами, подмышкам и лапам.','Не тяните колтуны и не вырезайте их ножницами у кожи: плотные спутывания лучше показать мастеру.','Перед купанием оцените спутывания: не пытайтесь отмыть плотные колтуны силой. Используйте косметику для собак и тщательно высушивайте шерсть.'],avoid:['Не обещать сохранение любой длины при плотных колтунах.','Не назначать одинаковую частоту купания всем питомцам.'],sources:careSources};
 return {kind:cat?'cat':'general',summary:cat?'Уход подбираем с учётом шерсти, возраста и того, как кошка переносит прикосновения, воду и сушку. Состав комплекса указан в карточке породы.':'Уход подбираем по типу шерсти, состоянию кожи и привычкам питомца. Основные процедуры берём из карточки породы, без автоматического добавления услуг.',home:[cat?'Бережно расчёсывайте шерсть подходящим инструментом; при стрессе остановитесь и обсудите спокойный формат с мастером.':'Аккуратно расчёсывайте шерсть подходящими инструментами, не выдёргивая спутывания.','Поддерживайте чистоту лап и наблюдайте за кожей. Стойкий неприятный запах, зуд или раздражение — повод обратиться к ветеринарному врачу.'],avoid:['Не советовать шампунь для людей, лекарства, чистку слухового прохода и седативные средства.'],sources:careSources};
}
export const puppyCare='Если это щенок или первое знакомство с уходом, начинайте с коротких спокойных прикосновений к лапам и шерсти, поощряйте спокойное поведение. Не заставляйте терпеть страх и не стремитесь выполнить весь комплекс за один раз. Подходящий формат первого визита уточняют по возрасту, состоянию здоровья и переносимости процедур; вопросы вакцинации обсуждают с ветеринарным врачом.';
